# ==============================================================
# Prokaryotic genome sequence loading and 6-channel one-hot encoding.
# Memory-based, PyTorch-friendly; no chunking.
# ==============================================================

import gzip
import bz2

import numpy as np

# 6 channels: A, C, G, T, N/default, softmask. Default (e.g. N) -> channel 4.
one_hot_table = np.zeros((256, 6), dtype=np.int32)
one_hot_table[:, 4] = 1
one_hot_table[ord("A"), :] = [1, 0, 0, 0, 0, 0]
one_hot_table[ord("C"), :] = [0, 1, 0, 0, 0, 0]
one_hot_table[ord("G"), :] = [0, 0, 1, 0, 0, 0]
one_hot_table[ord("T"), :] = [0, 0, 0, 1, 0, 0]
one_hot_table[ord("a"), :] = [1, 0, 0, 0, 0, 1]
one_hot_table[ord("c"), :] = [0, 1, 0, 0, 0, 1]
one_hot_table[ord("g"), :] = [0, 0, 1, 0, 0, 1]
one_hot_table[ord("t"), :] = [0, 0, 0, 1, 0, 1]


_COMPLEMENT_BASE = {
    "A": "T", "T": "A", "C": "G", "G": "C",
    "a": "t", "t": "a", "c": "g", "g": "c",
    "N": "N", "n": "n",
}


def reverse_complement_dna(sequence: str) -> str:
    """Reverse complement without constructing ``GenomeSequences``."""
    return "".join(_COMPLEMENT_BASE.get(base, base) for base in reversed(sequence))


class GenomeSequences:
    """In-memory genome sequences with 6-channel one-hot encoding. No chunking."""

    def __init__(
        self,
        fasta_file="",
        genome=None,
        np_file="",
        min_seq_len=0,
    ):
        self.fasta_file = fasta_file
        self.genome = genome
        self.np_file = np_file
        self.min_seq_len = min_seq_len
        self.sequences = []
        self.sequence_names = []
        self.one_hot_encoded = None
        if self.genome:
            self.extract_seqarray()
        elif self.fasta_file:
            self.read_fasta()
        else:
            self.load_np_array(self.np_file)

    def extract_seqarray(self):
        """Extract the sequence array from the genome object."""
        for name, seqrec in self.genome.items():
            if len(seqrec.seq) < self.min_seq_len:
                continue
            self.sequences.append(str(seqrec.seq))
            self.sequence_names.append(name)

    def read_fasta(self):
        """Read genome sequences from a FASTA file (plain, .gz, or .bz2)."""
        if self.fasta_file.endswith(".gz"):
            with gzip.open(self.fasta_file, "rt") as file:
                lines = file.readlines()
        elif self.fasta_file.endswith(".bz2"):
            with bz2.open(self.fasta_file, "rt") as file:
                lines = file.readlines()
        else:
            with open(self.fasta_file, "r") as file:
                lines = file.readlines()
        current_name = None
        current_sequence = ""
        for line in lines:
            if line.startswith(">"):
                if current_sequence and len(current_sequence) >= self.min_seq_len:
                    self.sequence_names.append(current_name)
                    self.sequences.append(current_sequence)
                # First token only (match GFF seqid parsing)
                current_name = line[1:].strip().split()[0]
                current_sequence = ""
            else:
                current_sequence += line.strip()
        if current_sequence and len(current_sequence) >= self.min_seq_len:
            self.sequence_names.append(current_name)
            self.sequences.append(current_sequence)

    def encode_sequences(self, seq=None):
        """One-hot encode the sequences and store in self.one_hot_encoded (shape (L, 6) per name)."""
        if seq is None:
            seq = self.sequence_names
        self.one_hot_encoded = {}
        for s in seq:
            sequence = self.sequences[self.sequence_names.index(s)]
            int_seq = np.frombuffer(sequence.encode("ascii"), dtype=np.uint8)
            self.one_hot_encoded[s] = one_hot_table[int_seq].copy()

    def get_full_encoded_sequence(self, seq_name: str) -> np.ndarray:
        """Return the full (L, 6) one-hot matrix for the given sequence name."""
        return self.one_hot_encoded[seq_name]

    def reverse_complement(self, sequence: str) -> str:
        """Return the reverse complement of the DNA sequence."""
        return reverse_complement_dna(sequence)

    def load_np_array(self, np_file: str):
        """Load one-hot encoded sequences from a numpy file into self.one_hot_encoded."""
        data = np.load(np_file, allow_pickle=True)
        if isinstance(data, np.ndarray) and data.dtype == object:
            self.one_hot_encoded = data.item()
        else:
            self.one_hot_encoded = dict(data)
        self.sequence_names = list(self.one_hot_encoded.keys())
